//! Per-style span box metrics.
//!
//! Every entry of the style table is a *span*: a styled range of text nested inside its parent
//! span, the root style being the outermost. On each line it intersects, a span generates a *span
//! box* (what CSS calls an inline box; Parley uses "inline box" for [`InlineBox`], an atomic box
//! embedded in the text). The root span box is the block container's "strut" (CSS 2 §10.8). This
//! module resolves, once per layout, the metrics of each span box from the span's first available
//! font and `line-height`, and computes the baseline shift implied by its `vertical-align`
//! relative to its parent.
//!
//! # Aligned subtrees
//!
//! CSS Inline Layout 3 §4.2.3 defines the *aligned subtree* of a span box recursively: it is that
//! box together with the aligned subtrees of each child span box (or [`InlineBox`]) whose
//! `vertical-align` is parent-relative (`baseline`, `sub`, `super`, `text-top`, `text-bottom`,
//! `middle`, or a `<length>`/`<percentage>`). Children with `vertical-align: top | bottom` are
//! aligned to the line box instead, so they and their descendants are left out.
//!
//! By that definition every span box has an aligned subtree, most of them nested inside their
//! parent's. The ones that matter for layout are those that are not part of a larger one, which
//! Parley calls *independent aligned subtrees* (our term; the specifications don't name them).
//! Their roots are the root span box, whose subtree is the *root aligned subtree*, and every box
//! with `vertical-align: top | bottom`. They don't overlap, and each box on a line belongs to
//! exactly one of them: the one rooted at its nearest ancestor (or self) with
//! `vertical-align: top | bottom`, or the root aligned subtree if there is none (see
//! [`StyleMetrics::aligned_subtree_root`]). Where the rest of this crate says just "aligned
//! subtree", it means an independent one. For example, with these spans:
//!
//! ```text
//! root
//! ├─ a (super)
//! │  └─ b (baseline)
//! └─ c (top)
//!    └─ d (sub)
//! ```
//!
//! the CSS definition gives five aligned subtrees (`{root, a, b}`, `{a, b}`, `{b}`, `{c, d}` and
//! `{d}`), of which two are independent: `{root, a, b}` (the root aligned subtree) and `{c, d}`.
//!
//! Within an independent aligned subtree all baselines are fixed relative to each other, so its
//! extents can be accumulated relative to the root's baseline while the line is being built; the
//! independent aligned subtrees are only positioned against each other, and the line box sized,
//! once the line is complete.
//! See <https://drafts.csswg.org/css-inline-3/#aligned-subtree> and CSS 2 §10.8
//! <https://www.w3.org/TR/CSS22/visudet.html#line-height>.

use alloc::vec::Vec;

#[cfg(feature = "libm")]
#[allow(unused_imports)]
use core_maths::CoreFloat;
use fontique::{Query, QueryFamily};
use parley_engine::{FontInstance, FontMetrics, ShapedText};

use crate::resolve::{ResolveContext, ResolvedStyle};
use crate::style::{round_to, Brush};
use crate::{AlignmentBaseline, BaselineShift, FontContext, FontData, InlineBox, VerticalAlign};

/// Metrics of the span box generated by one style table entry.
///
/// All distances are in layout units and measured from the box's own baseline; `over`/`ascent`
/// extend upwards, `under`/`descent` downwards.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub(crate) struct StyleMetrics {
    /// Ascent of the first available font (the top of the content area).
    pub(crate) ascent: f32,
    /// Descent of the first available font (the bottom of the content area).
    pub(crate) descent: f32,
    /// x-height of the first available font, used by `vertical-align: middle`.
    pub(crate) x_height: f32,
    /// pyro: cap height of the first available font (the ascent for a font without one).
    pub(crate) cap_height: f32,
    /// pyro: the ideographic em box and character face box of the first available font, as
    /// distances over and under the baseline (`[em over, em under, face over, face under]`).
    pub(crate) ideographic: [f32; 4],
    /// pyro: the alphabetic, hanging and mathematical baselines of the first available font, as
    /// heights over the glyph origin: its `BASE` table's, else 0, 80% and half of the ascent
    /// (Blink's synthesized ones).
    pub(crate) named: [f32; 3],
    /// pyro: distance from the baseline to the top of the content area: the ascent, or the edge
    /// `text-box-trim` trims it to.
    pub(crate) content_over: f32,
    /// pyro: distance from the baseline to the bottom of the content area: the descent, or the
    /// edge `text-box-trim` trims it to.
    pub(crate) content_under: f32,
    /// Distance from the baseline to the top of the line-height expanded span box.
    pub(crate) over: f32,
    /// Distance from the baseline to the bottom of the line-height expanded span box.
    pub(crate) under: f32,
    /// Offset of this box's baseline above the baseline of the root of the
    /// [independent aligned subtree] it belongs to.
    ///
    /// [independent aligned subtree]: Self::aligned_subtree_root
    pub(crate) baseline_offset: f32,
    /// [`Self::baseline_offset`] before quantization. Children accumulate their shifts from this
    /// so that rounding never compounds along the ancestor chain.
    pub(crate) exact_baseline_offset: f32,
    /// Style index of the root of the [independent aligned subtree] this box belongs to: the
    /// nearest ancestor (or self) with `vertical-align: top | bottom`, or `0` (the root span box)
    /// if there is none.
    ///
    /// [independent aligned subtree]: self#aligned-subtrees
    pub(crate) aligned_subtree_root: u16,
    /// Style index of the parent span; always less than the span's own index, except for the
    /// root (index `0`), whose parent is `0`.
    pub(crate) parent: u16,
    /// The style's font size, against which `sub`/`super` of children are resolved.
    pub(crate) font_size: f32,
    /// pyro: the metrics of the first available font, unrounded, which a line that `text-fit`
    /// scales scales ([`scale_style_metrics`]).
    pub(crate) font: Option<FontMetrics>,
    /// pyro: the space over and under the content area that annotations (emphasis marks) take.
    pub(crate) annotation: [f32; 2],
    /// pyro: [`Self::over`] and [`Self::under`] before annotations grew them (see
    /// `LineMetrics::annotation_overflow`).
    pub(crate) bare: [f32; 2],
}

/// Resolve the [`StyleMetrics`] of every style in `styles`, in table order.
///
/// Relies on the style table being ordered parent-first (`style.parent <= index`), which both
/// style builders guarantee. `shaped_text` is the already shaped text of the layout, whose run
/// metrics are reused where a style's first available font was also used for shaping.
/// `first_fonts` holds, per style, the first available font the shaper's font selector found
/// (pyro; see `shape::FontSelector`); a style without one is queried here.
pub(crate) fn resolve_style_metrics<B: Brush>(
    rcx: &ResolveContext,
    fcx: &mut FontContext,
    styles: &[ResolvedStyle<B>],
    shaped_text: &ShapedText,
    first_fonts: &[Option<FontInstance>],
    quantum: f32,
    out: &mut Vec<StyleMetrics>,
) {
    let quantize = quantum > 0.;
    out.clear();
    out.reserve(styles.len());

    let mut query = fcx.collection.query(&mut fcx.source_cache);

    for (index, style) in styles.iter().enumerate() {
        let queried;
        let font = match first_fonts.get(index).and_then(Option::as_ref) {
            Some(font) => Some(font),
            None => {
                queried = first_available_font(&mut query, rcx, style);
                queried.as_ref()
            }
        };
        // pyro: a face's `size-adjust` is not applied where `font-size-adjust` sets the size.
        let unadjusted;
        let font = match font {
            Some(font) if style.font_size_adjusted && font.synthesis.size_adjust() != 1.0 => {
                unadjusted = FontInstance {
                    font: font.font.clone(),
                    synthesis: font.synthesis.without_size_adjust(),
                };
                Some(&unadjusted)
            }
            font => font,
        };
        let font_metrics = font
            .and_then(|font| {
                let variations = rcx.variations(style.font_variations).unwrap_or(&[]);
                shaped_run_metrics(shaped_text, font, style.font_size, variations)
                    .or_else(|| FontMetrics::from_font_instance(font, style.font_size, variations))
            })
            .unwrap_or_else(|| FontMetrics::fallback(style.font_size));

        let line_height = style
            .line_height
            .resolve(style.font_size, &font_metrics, quantum);

        let mut metrics = StyleMetrics::from_font(&font_metrics, line_height, quantum);
        metrics.font_size = style.font_size;
        metrics.font = Some(font_metrics);
        // pyro: the ideographic boxes: the font's `BASE` table, else derived from the em box as
        // Blink derives them (the em box sits on the descent; the face box is 5% of the em in).
        {
            let em = style.font_size;
            let base = font
                .and_then(|font| parley_engine::IdeographicBaselines::from_font_instance(font, em))
                .unwrap_or_default();
            let under = base.ideographic_under.map_or(metrics.descent, |v| -v);
            let over = base.ideographic_over.unwrap_or(em - under);
            let face_under = base.face_under.map_or(under - em * 0.05, |v| -v);
            let face_over = base.face_over.unwrap_or(over - em * 0.05);
            metrics.ideographic = [over, under, face_over, face_under];
            metrics.named = [
                base.alphabetic.unwrap_or(0.),
                base.hanging.unwrap_or(metrics.ascent * 0.8),
                base.math.unwrap_or(metrics.ascent / 2.),
            ];
        }
        if let Some(edge) = style.text_box_trim.over {
            metrics.content_over = metrics.text_edge(edge, true);
        }
        if let Some(edge) = style.text_box_trim.under {
            metrics.content_under = metrics.text_edge(edge, false);
        }
        // pyro: what is drawn over or under the span's text (ruby annotations, emphasis marks)
        // takes room beyond its content area; the span box grows to hold it where its line height
        // leaves too little (CSS Ruby 1, 4.4).
        let space = style.annotation_space;
        metrics.annotation = [space.over, space.under];
        metrics.bare = [metrics.over, metrics.under];
        if space.over > 0. {
            metrics.over = metrics.over.max(metrics.ascent + space.over);
        }
        if space.under > 0. {
            metrics.under = metrics.under.max(metrics.descent + space.under);
        }

        // pyro: the first line's root (`::first-line`, its own parent) is a root span box too.
        if index == 0 || usize::from(style.parent) == index {
            // The root span box (the strut).
            metrics.parent = index as u16;
            metrics.baseline_offset = 0.;
            metrics.exact_baseline_offset = 0.;
            metrics.aligned_subtree_root = 0;
        } else {
            let parent_index = usize::from(style.parent);
            debug_assert!(
                parent_index < index,
                "style table must be ordered parent-first"
            );
            // Never let a malformed table create an orphaned span; treat it as a child of the root.
            let parent_index = if parent_index < index {
                parent_index
            } else {
                0
            };
            metrics.parent = parent_index as u16;
            let parent = &out[parent_index];
            let align = style.vertical_align;
            if align.is_line_relative() {
                metrics.baseline_offset = 0.;
                metrics.exact_baseline_offset = 0.;
                metrics.aligned_subtree_root = index as u16;
            } else {
                let own = Some((metrics.ascent, metrics.descent, metrics.x_height));
                let named = Some(metrics.named_baselines());
                let shift = shift_from_parent(align, metrics.over, metrics.under, own, named, parent);
                metrics.exact_baseline_offset = parent.exact_baseline_offset + shift;
                // Rounded once from the accumulated offset (not per level) so the total error
                // stays within half a pixel.
                metrics.baseline_offset = if quantize {
                    round_half_up(metrics.exact_baseline_offset)
                } else {
                    metrics.exact_baseline_offset
                };
                metrics.aligned_subtree_root = parent.aligned_subtree_root;
            }
        }

        out.push(metrics);
    }
}

/// pyro: appends to `out` the span box metrics `base` (the layout's) have at `scale` times their
/// font sizes, for a line CSS `text-fit` scales: Blink scales the text metrics of such a line's
/// boxes, and their line heights unless those are lengths; the space emphasis marks take scales
/// with the text. (Ruby turns `text-fit` off in Blink.)
pub(crate) fn scale_style_metrics<B: Brush>(
    styles: &[crate::layout::Style<B>],
    base: &[StyleMetrics],
    scale: f32,
    quantum: f32,
    out: &mut Vec<StyleMetrics>,
) {
    let quantize = quantum > 0.;
    let start = out.len();
    for (index, (style, base)) in styles.iter().zip(base).enumerate() {
        let font = base
            .font
            .unwrap_or_else(|| FontMetrics::fallback(base.font_size))
            .scaled(scale);
        let font_size = base.font_size * scale;
        let line_height = style.line_height.resolve(font_size, &font, quantum);
        // A percentage `vertical-align` scales with the line height.
        let base_line_height = style.line_height.resolve(
            base.font_size,
            &base.font.unwrap_or_else(|| FontMetrics::fallback(base.font_size)),
            quantum,
        );
        let mut metrics = StyleMetrics::from_font(&font, line_height, quantum);
        metrics.font = Some(font);
        metrics.font_size = font_size;
        metrics.ideographic = base.ideographic.map(|value| value * scale);
        metrics.named = base.named.map(|value| value * scale);
        // A side `text-box-trim` trims stays trimmed (to its scaled edge).
        if base.content_over != base.ascent {
            metrics.content_over = base.content_over * scale;
        }
        if base.content_under != base.descent {
            metrics.content_under = base.content_under * scale;
        }
        let [over, under] = base.annotation;
        metrics.annotation = [over * scale, under * scale];
        metrics.bare = [metrics.over, metrics.under];
        if over > 0. {
            metrics.over = metrics.over.max(metrics.ascent + over * scale);
        }
        if under > 0. {
            metrics.under = metrics.under.max(metrics.descent + under * scale);
        }
        metrics.parent = base.parent;
        if index > 0 && usize::from(base.parent) != index {
            let align = style.vertical_align;
            if align.is_line_relative() {
                metrics.aligned_subtree_root = index as u16;
            } else {
                let parent = &out[start + usize::from(base.parent).min(index - 1)];
                let own = Some((metrics.ascent, metrics.descent, metrics.x_height));
                let mut align = align;
                if let BaselineShift::LineHeight(length) = &mut align.shift
                    && base_line_height != 0.
                {
                    *length *= line_height / base_line_height;
                }
                let named = Some(metrics.named_baselines());
                let shift = shift_from_parent(align, metrics.over, metrics.under, own, named, parent);
                metrics.exact_baseline_offset = parent.exact_baseline_offset + shift;
                metrics.baseline_offset = if quantize {
                    round_half_up(metrics.exact_baseline_offset)
                } else {
                    metrics.exact_baseline_offset
                };
                metrics.aligned_subtree_root = parent.aligned_subtree_root;
            }
        }
        out.push(metrics);
    }
}

/// The metrics of a shaped run using `font` at `font_size`, if any: the shaper has then already
/// computed the metrics this style needs. Only used at the font's default variation location,
/// which covers the common non-variable-font case without re-resolving axes.
fn shaped_run_metrics(
    shaped_text: &ShapedText,
    font: &FontInstance,
    font_size: f32,
    variations: &[crate::FontVariation],
) -> Option<FontMetrics> {
    if !variations.is_empty() || !font.synthesis.variation_settings().is_empty() {
        return None;
    }
    let font_index = shaped_text.fonts().iter().position(|f| f == font)?;
    let coords = shaped_text.normalized_coords();
    shaped_text
        .runs()
        .iter()
        .find(|run| {
            run.font_index == font_index
                && run.font_size.to_bits() == font_size.to_bits()
                && coords[run.normalized_coords_range.clone()]
                    .iter()
                    .all(|c| c.to_bits() == 0)
        })
        .map(|run| run.font_metrics)
}

/// The line-height expanded box of a font at a resolved `line-height`: the font's content area
/// (`ascent`/`descent`) with the leading distributed around it (`over`/`under`).
///
/// All distances are measured from the box's own baseline; `over`/`ascent` extend upwards,
/// `under`/`descent` downwards.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub(crate) struct BoxMetrics {
    /// Ascent of the font (the top of the content area).
    pub(crate) ascent: f32,
    /// Descent of the font (the bottom of the content area).
    pub(crate) descent: f32,
    /// Distance from the baseline to the top of the line-height expanded box.
    pub(crate) over: f32,
    /// Distance from the baseline to the bottom of the line-height expanded box.
    pub(crate) under: f32,
    /// pyro: [`Self::over`] and [`Self::under`] without the room annotations take.
    pub(crate) bare: [f32; 2],
    /// pyro: the extent of what is drawn over and under the baseline: the content area and the
    /// annotations beyond it.
    pub(crate) marks: [f32; 2],
}

impl BoxMetrics {
    /// The box of `font` expanded to `line_height`.
    ///
    /// The half-leading is distributed as in CSS 2 §10.8.1. With a `quantum` (pyro: the layout
    /// units of a CSS pixel; 0 for none), ascent and descent are rounded to whole CSS pixels
    /// (Blink's `FontMetrics`) and the leading above the baseline is floored to whole CSS pixels
    /// (Blink's `FontHeight::AddLeading`), at any device scale.
    pub(crate) fn from_font(font: &FontMetrics, line_height: f32, quantum: f32) -> Self {
        let quantize = quantum > 0.;
        let (ascent, descent) = if quantize {
            (round_to(font.ascent, quantum), round_to(font.descent, quantum))
        } else {
            (font.ascent, font.descent)
        };
        let half_leading = (line_height - (ascent + descent)) / 2.;
        let over = if quantize {
            // In Chromium's layout units (1/64 CSS px), whose division truncates: a line height
            // one unit short of the content area leaves no half-leading, not a whole pixel of it.
            let leading = ((line_height - (ascent + descent)) * 64. / quantum).round();
            ascent + ((leading / 2.).trunc() / 64.).floor() * quantum
        } else {
            ascent + half_leading
        };
        Self::new(ascent, descent, over, line_height - over)
    }

    /// pyro: a box without annotations.
    pub(crate) fn new(ascent: f32, descent: f32, over: f32, under: f32) -> Self {
        Self { ascent, descent, over, under, bare: [over, under], marks: [ascent, descent] }
    }

    /// pyro: a span's box, with the room its annotations take (`StyleMetrics::annotation`).
    pub(crate) fn span(metrics: &StyleMetrics) -> Self {
        let [over, under] = metrics.annotation;
        Self {
            ascent: metrics.ascent,
            descent: metrics.descent,
            over: metrics.over,
            under: metrics.under,
            bare: metrics.bare,
            marks: [
                metrics.ascent + over.max(0.),
                metrics.descent + under.max(0.),
            ],
        }
    }
}

impl StyleMetrics {
    /// The font-derived metrics of a span box: its [`BoxMetrics`] and x-height. The remaining
    /// fields describe the box's place in the style tree and are filled in by
    /// [`resolve_style_metrics`].
    fn from_font(font: &FontMetrics, line_height: f32, quantum: f32) -> Self {
        let quantize = quantum > 0.;
        let box_metrics = BoxMetrics::from_font(font, line_height, quantum);
        // Fonts without an `OS/2.sxHeight` get the same estimate Gecko and Blink use
        // (`DEFAULT_XHEIGHT_FACTOR`); css-inline-3 §A.2 suggests measuring the `x` glyph or
        // `0.5em` instead, but this keeps us in line with browsers.
        let x_height = font.x_height.unwrap_or(box_metrics.ascent * 0.56);
        Self {
            ascent: box_metrics.ascent,
            descent: box_metrics.descent,
            x_height: if quantize { x_height.round() } else { x_height },
            cap_height: font.cap_height.unwrap_or(box_metrics.ascent),
            ideographic: [0.; 4],
            named: [0., box_metrics.ascent * 0.8, box_metrics.ascent / 2.],
            content_over: box_metrics.ascent,
            content_under: box_metrics.descent,
            over: box_metrics.over,
            under: box_metrics.under,
            baseline_offset: 0.,
            exact_baseline_offset: 0.,
            aligned_subtree_root: 0,
            parent: 0,
            font_size: 0.,
            font: None,
            annotation: [0.; 2],
            bare: [box_metrics.over, box_metrics.under],
        }
    }
}

impl StyleMetrics {
    /// pyro: the distance from the baseline to a font metric edge (CSS Inline 3 `<text-edge>`):
    /// upwards for an over edge, downwards for an under edge.
    pub(crate) fn text_edge(&self, edge: crate::TextEdge, over: bool) -> f32 {
        use crate::TextEdge::*;
        match (edge, over) {
            (Text, true) => self.ascent,
            (Text, false) => self.descent,
            (Cap, true) => self.cap_height,
            (Ex, true) => self.x_height,
            (Alphabetic, false) => 0.,
            (Ideographic, true) => self.ideographic[0],
            (Ideographic, false) => self.ideographic[1],
            (IdeographicInk, true) => self.ideographic[2],
            (IdeographicInk, false) => self.ideographic[3],
            // Not edges of that side: the text edge.
            (Cap | Ex, false) => self.descent,
            (Alphabetic, true) => self.ascent,
        }
    }
}

/// pyro: a span's baselines as heights over its glyph origin (`StyleMetrics::named_baselines`).
#[derive(Clone, Copy, Debug)]
pub(crate) struct NamedBaselines {
    pub(crate) alphabetic: f32,
    pub(crate) ideographic: f32,
    pub(crate) central: f32,
    pub(crate) math: f32,
    pub(crate) hanging: f32,
}

impl StyleMetrics {
    /// pyro: the span's alphabetic, ideographic (under), central (the ideographic em box's
    /// middle), mathematical and hanging baselines over its glyph origin.
    pub(crate) fn named_baselines(&self) -> NamedBaselines {
        NamedBaselines {
            alphabetic: self.named[0],
            ideographic: -self.ideographic[1],
            central: (self.ideographic[0] - self.ideographic[1]) / 2.,
            math: self.named[2],
            hanging: self.named[1],
        }
    }
}

/// The baseline shift (positive upwards) of a box extending `over` above and `under` below its
/// baseline, relative to the baseline of its `parent` span box, for a parent-relative
/// `vertical-align` value: the `alignment-baseline` offset plus the `baseline-shift`.
/// Line-relative values (`top`, `bottom`) yield no shift.
pub(crate) fn shift_from_parent(
    align: VerticalAlign,
    over: f32,
    under: f32,
    // pyro: a span's own font ascent, descent and x-height (none for an inline box).
    own: Option<(f32, f32, f32)>,
    // pyro: a span's own named baselines (none for an inline box, whose baselines are
    // synthesized from its edges: alphabetic and ideographic its under edge, central and
    // mathematical its middle, hanging its over edge).
    named: Option<NamedBaselines>,
    parent: &StyleMetrics,
) -> f32 {
    let parent_named = parent.named_baselines();
    let alignment = match (align.alignment, own) {
        // pyro: the dominant baseline, alphabetic: a font's `BASE` alphabetic baseline need
        // not be its glyph origin (WPT css-inline `alignment-baseline-horizontal-002`).
        (AlignmentBaseline::Baseline | AlignmentBaseline::Alphabetic, _) => {
            parent_named.alphabetic - named.map_or(0., |own| own.alphabetic)
        }
        (AlignmentBaseline::Ideographic, _) => {
            parent_named.ideographic - named.map_or(-under, |own| own.ideographic)
        }
        (AlignmentBaseline::Central, _) => {
            parent_named.central - named.map_or((over - under) / 2., |own| own.central)
        }
        (AlignmentBaseline::Mathematical, _) => {
            parent_named.math - named.map_or((over - under) / 2., |own| own.math)
        }
        (AlignmentBaseline::Hanging, _) => parent_named.hanging - named.map_or(over, |own| own.hanging),
        (AlignmentBaseline::TextTop, _) | (AlignmentBaseline::TextOver, None) => parent.ascent - over,
        (AlignmentBaseline::TextBottom, _) | (AlignmentBaseline::TextUnder, None) => under - parent.descent,
        (AlignmentBaseline::Middle, _) => parent.x_height / 2. - (over - under) / 2.,
        // (A box's x-middle baseline is synthesized as Blink does it here: its alphabetic
        // baseline; WPT css-inline `alignment-baseline-horizontal-003`.)
        (AlignmentBaseline::XMiddle, None) => 0.,
        (AlignmentBaseline::TextOver, Some((ascent, _, _))) => parent.ascent - ascent,
        (AlignmentBaseline::TextUnder, Some((_, descent, _))) => descent - parent.descent,
        (AlignmentBaseline::XMiddle, Some((_, _, x_height))) => parent.x_height / 2. - x_height / 2.,
    };
    let shift = match align.shift {
        BaselineShift::Length(length) | BaselineShift::LineHeight(length) => length,
        // Constants as used by WebKit and Blink.
        BaselineShift::Sub => -(parent.font_size / 5.),
        BaselineShift::Super => parent.font_size / 3.,
        BaselineShift::Top | BaselineShift::Bottom => 0.,
    };
    alignment + shift
}

/// Where an in-flow [`InlineBox`] sits relative to the baseline of the independent aligned
/// subtree it belongs to.
#[derive(Clone, Copy, Debug)]
pub(crate) struct InlineBoxPlacement {
    /// Style index of the aligned subtree root (see [`StyleMetrics::aligned_subtree_root`]).
    pub(crate) aligned_subtree_root: u16,
    /// Offset of the box's baseline above the subtree root's baseline.
    pub(crate) baseline_offset: f32,
    /// Height of the box above its baseline.
    pub(crate) ascent: f32,
    /// Height of the box below its baseline.
    pub(crate) descent: f32,
}

/// Resolve the parent-relative alignment of `inline_box` against the span box of the style
/// containing it (`parent_style`).
///
/// A box without an explicit baseline sits on the baseline, i.e. it is all ascent. For
/// `vertical-align: top | bottom` the returned offset is relative to the subtree the parent
/// belongs to, but such boxes are positioned against the line box instead (see
/// [`crate::Line::inline_box_top`]).
pub(crate) fn inline_box_placement(
    inline_box: &InlineBox,
    parent_style: u16,
    style_metrics: &[StyleMetrics],
    quantize: bool,
    // pyro: [`crate::Layout::set_central_baseline`].
    central: bool,
) -> InlineBoxPlacement {
    // pyro: on a central baseline the box's `baseline` is its central one, which only baseline
    // alignment uses; the other alignments take its synthesized alphabetic baseline (its
    // line-under edge), as on an alphabetic line.
    let central = central && inline_box.central;
    let central_baseline = central
        && inline_box.vertical_align.alignment == AlignmentBaseline::Baseline
        && !inline_box.vertical_align.is_line_relative();
    let ascent = if central && !central_baseline {
        inline_box.height
    } else {
        inline_box.baseline.unwrap_or(inline_box.height)
    };
    let descent = inline_box.height - ascent;
    let parent = style_metrics
        .get(usize::from(parent_style))
        .copied()
        .unwrap_or_default();
    let shift = shift_from_parent(inline_box.vertical_align, ascent, descent, None, None, &parent);
    // pyro: on a central baseline the box's own (central) baseline goes to the middle of the
    // parent's content area, over its alphabetic baseline by half of ascent minus descent. Not
    // quantized: the content area's middle is where the dominant baseline of the line is
    // measured and where the strut of a zero line height sits.
    let central_shift = if central_baseline { (parent.ascent - parent.descent) / 2. } else { 0. };
    let baseline_offset = parent.exact_baseline_offset + shift;
    InlineBoxPlacement {
        aligned_subtree_root: parent.aligned_subtree_root,
        baseline_offset: if quantize {
            round_half_up(baseline_offset) + central_shift
        } else {
            baseline_offset + central_shift
        },
        ascent,
        descent,
    }
}

/// The [first available font] of `style`.
///
/// [first available font]: https://drafts.csswg.org/css-fonts-4/#first-available-font
fn first_available_font<B: Brush>(
    query: &mut Query<'_>,
    rcx: &ResolveContext,
    style: &ResolvedStyle<B>,
) -> Option<FontInstance> {
    let families = rcx.stack(style.font_family).unwrap_or(&[]);
    query.set_families(families.iter().copied().map(QueryFamily::Id));
    query.set_attributes(fontique::Attributes {
        width: style.font_width,
        weight: style.font_weight,
        style: style.font_style,
    });
    let font = query.first_available_font()?;
    Some(FontInstance {
        font: FontData {
            data: font.blob,
            index: font.index,
        },
        synthesis: font.synthesis,
    })
}

/// pyro: rounds to the nearest whole unit, halves up (towards positive infinity), as Blink snaps
/// a layout position to a pixel: an empty inline-block with `vertical-align: -7.5px` and
/// `margin-bottom: 7.5px` sits on the baseline, where rounding halves away from zero put it a
/// pixel low (WPT CSS2 `visudet/inline-block-baseline-011`, `-014`).
fn round_half_up(value: f32) -> f32 {
    (value + 0.5).floor()
}
